const char *link_path = "/tmp/link_to_file";
const char *attr_name = "user.metadata";
int status;

// Removes attribute from the symbolic link itself.
status = lremovexattr(link_path, attr_name);

if (status == -1) {
    if (errno == ENODATA) {
        // Attribute not present on the link
    } else {
        // EPERM, EACCES, ENOENT, etc.
    }
}
// status == 0 on success.
